                                        <td>old_password</td>
                                        <td>required, string</td>
                                    </tr>
                                    <tr>
                                        <td>password</td>
                                        <td>required, string, mixed case + numbers  <br>  <br>eg.  <br>Password123</td>
                                    </tr>
                                    <tr>
                                        <td>password_confirmation</td>
